function draft(){let o=$('offer').value.trim(),a=$('audience').value.trim()||'your ideal customer',g=$('goal').value,t=$('tone').value,f=$('format').value;if(!o)return note('Enter an offer or topic first.');let hook='A simpler way to '+g.toLowerCase()+'.',cta='Want the details? Reply INFO or visit your offer page.';if(f==='email')return 'SUBJECT: A practical next step for '+o+'\n\nHi there,\n\nYou do not need more noise. You need a clear next step. I created '+o+' to help '+a+' move forward.\n\nHere is a simple way to start:\n1. Choose one measurable outcome.\n2. Make the next action small and repeatable.\n3. Review what worked each week.\n\n'+cta+'\n\nBest,\nYour name\n\nInclude your valid unsubscribe mechanism before sending.';if(f==='ad')return 'AD 1 — '+hook+' '+o+' helps '+a+' take action. '+cta+'\n\nAD 2 — Ready for a more focused approach? Discover '+o+'. '+cta+'\n\nAD 3 — Less overwhelm. More forward motion. Explore '+o+' today.';if(f==='blog')return 'SEO OUTLINE: '+o+'\nSearch intent: practical / informational\nAudience: '+a+'\n\nH1: A practical guide to '+o+'\nH2: What matters and why\nH2: Common mistakes to avoid\nH2: A step-by-step approach\nH2: Tools and resources\nH2: Frequently asked questions\n\nMeta: A practical guide for '+a+' exploring '+o+'.';if(f==='launch')return 'LAUNCH PLAN — '+o+'\n\nPRE-LAUNCH: Share the problem, ask your audience what they need, collect opt-ins.\nLAUNCH: Explain the outcome, show the offer, answer objections, use one clear CTA.\nFOLLOW-UP: Share a tutorial, genuine proof, FAQs and a final reminder.\n\nAudience: '+a+'\nGoal: '+g+'\nVoice: '+t+'\nCTA: '+cta;return 'SOCIAL CONTENT PACK — '+o+'\n\nPOST 1 · HOOK\n'+hook+' '+o+' is designed for '+a+'.\n\nPOST 2 · EDUCATION\nThree steps to make progress: choose one outcome, make the next action repeatable, review weekly.\n\nPOST 3 · OFFER\nBuilt for '+a+': '+o+'. '+cta+'\n\nPOST 4 · CONVERSATION\nWhat is slowing your progress right now? Tell me below.\n\nPOST 5 · REMINDER\nConsistency beats complexity. Pick one useful action and repeat it.\n\nVoice: '+t+'. Add your real examples, evidence and destination link before publishing.'}async function generate(){let b=$('generate');b.disabled=true;b.textContent='Creating…';try{let text;if(s.settings.aiEndpoint){let r=await fetch(s.settings.aiEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({offer:$('offer').value,audience:$('audience').value,goal:$('goal').value,tone:$('tone').value,format:$('format').value})});if(!r.ok)throw Error('AI endpoint returned '+r.status);let d=await r.json();text=d.text||d.content||d.output;if(!text)throw Error('Endpoint must return text, content or output.')}else text=draft();$('output').textContent=text;log('Generated '+$('format').value+' content draft');if(!s.settings.aiEndpoint)note('Local starter draft created. Connect an AI endpoint for live AI.')}catch(e){note('Generation failed: '+e.message)}finally{b.disabled=false;b.textContent='✧ Generate content →'}}$('generate').onclick=generate;$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('output').textContent);note('Copied.')}catch{note('Clipboard unavailable.')}};$('saveDraft').onclick=()=>{let text=$('output').textContent;if(!text||text.startsWith('Your next great'))return note('Generate a draft first.');s.drafts.unshift({text,created:new Date().toISOString()});save();log('Saved content draft');note('Draft saved locally.')};
