$('seoBuild').onclick=()=>{let t=$('seoTopic').value.trim(),a=$('seoAudience').value.trim()||'your audience';if(!t)return note('Enter a topic first.');$('seoOutput').textContent='SEO PLAN: '+t+'\nAudience: '+a+'\n\nKeyword ideas: '+t+' guide; how to '+t+'; best '+t+' for '+a+'; '+t+' examples; '+t+' mistakes.\n\n1. Publish a useful pillar guide answering the main question.\n2. Create three supporting articles for related questions.\n3. Link related pages naturally.\n4. Add a relevant opt-in resource and clear CTA.\n5. Review Search Console impressions, clicks and conversions after indexing.\n\nValidate search demand and competition before investing; avoid keyword stuffing.';log('Built SEO plan for '+t)};
$('addLead').onclick=async()=>{let email=$('leadEmail').value.trim().toLowerCase();if(!/^\S+@\S+\.\S+$/.test(email))return note('Enter a valid email.');if(!$('leadConsent').checked)return note('Confirm permission to store and contact this lead.');if(s.leads.some(x=>x.email===email))return note('Email already exists.');const attributionAllowed=$('leadAttributionConsent').checked;let lead={email,name:$('leadName').value.trim(),source:$('leadSource').value,consentAt:new Date().toISOString(),createdAt:new Date().toISOString(),attributionConsentAt:attributionAllowed&&sessionAttribution?new Date().toISOString():null,attribution:attributionAllowed&&sessionAttribution?{...sessionAttribution}:null};if(lead.attribution){try{const key='autopilot-first-touch-utm-v1';if(!sessionStorage.getItem(key))sessionStorage.setItem(key,JSON.stringify(lead.attribution))}catch{lead.attribution=null;lead.attributionConsentAt=null}}try{if(s.settings.leadEndpoint){let r=await fetch(s.settings.leadEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(lead)});if(!r.ok)throw Error('Endpoint returned '+r.status)}lead.id=Date.now();lead.status='active';lead.tags=[];lead.notes='';s.leads.unshift(lead);dispatchLocalWorkflow('lead_created',lead);save();render();log('Captured opted-in lead');$('leadEmail').value='';$('leadName').value='';$('leadConsent').checked=false;$('leadAttributionConsent').checked=false;note(s.settings.leadEndpoint?'Lead saved and sent to endpoint.':'Lead saved on this device.')}catch(e){note('Lead not saved: '+e.message)}};

