function renderSequences(){list('sequenceList',s.sequences||[],'No sequence plans saved yet.',x=>'<div class="stackitem"><div><b>'+esc(x.name)+'</b><small>'+esc(x.trigger)+' · '+x.steps.length+' planned emails</small><small>'+esc(x.steps[0]?.subject||'No subject')+'</small></div><button data-del-seq="'+x.id+'">✕</button></div>')}
