$('leadList').onclick=e=>{const convert=e.target.closest('[data-convert-l]'),edit=e.target.closest('[data-edit-l]'),del=e.target.closest('[data-del-l]');if(convert){const l=s.leads.find(x=>String(x.id)===convert.dataset.convertL);if(!l)return;if(l.conversionAt){delete l.conversionAt;delete l.conversionType;log('Removed conversion mark for '+l.email)}else{l.conversionAt=new Date().toISOString();l.conversionType='manual_lead_conversion';log('Marked lead as converted: '+l.email)}save();renderLeads();renderLeadAttribution();note(l.conversionAt?'Conversion recorded as a manual lead outcome.':'Conversion mark removed.')}if(edit){const l=s.leads.find(x=>String(x.id)===edit.dataset.editL);if(!l)return;selectedLeadId=l.id;$('crmSelected').value=l.name||l.email;$('crmStatus').value=l.status||'active';$('crmTags').value=(l.tags||[]).join(', ');$('crmNotes').value=l.notes||''}if(del){s.leads=s.leads.filter(x=>String(x.id)!==del.dataset.delL);if(String(selectedLeadId)===del.dataset.delL)selectedLeadId=null;save();renderLeads();log('Removed contact')}}
$('saveCrm').onclick=()=>{const l=s.leads.find(x=>String(x.id)===String(selectedLeadId));if(!l)return note('Choose a contact to edit first.');const oldTags=[...(l.tags||[])];l.status=$('crmStatus').value;l.tags=[...new Set($('crmTags').value.split(',').map(x=>x.trim().toLowerCase()).filter(Boolean))];l.notes=$('crmNotes').value.trim();const added=l.tags.filter(t=>!oldTags.includes(t));save();added.forEach(()=>dispatchLocalWorkflow('tag_added',l));renderLeads();log('Updated CRM profile for '+l.email);note('Contact profile updated.')};
$('saveSequence').onclick=()=>{const name=$('seqName').value.trim(),s1=$('seqSubject1').value.trim(),b1=$('seqBody1').value.trim(),s2=$('seqSubject2').value.trim(),b2=$('seqBody2').value.trim(),delay=Number($('seqDelay').value);if(!name||!s1||!b1)return note('Add a sequence name and the first email subject and message.');if((s2&&!b2)||(!s2&&b2)||!Number.isInteger(delay)||delay<1||delay>90)return note('Complete both fields for step two, and use a delay from 1 to 90 days.');s.sequences=s.sequences||[];const steps=[{subject:s1,body:b1,delayDays:0}];if(s2)steps.push({subject:s2,body:b2,delayDays:delay});s.sequences.unshift({id:Date.now(),name,trigger:$('seqTrigger').value,steps,createdAt:new Date().toISOString()});save();renderSequences();log('Saved email sequence plan: '+name);$('seqName').value='';$('seqSubject1').value='';$('seqBody1').value='';$('seqSubject2').value='';$('seqBody2').value='';note('Sequence plan saved; no email was sent.')};
